/** PWA plumbing for the approver: service worker, Web Push and the install prompt. */
import { useCallback, useEffect, useState } from 'react';
import type { ApiClient } from '../shared/api/client';
import { localStore } from '../shared/lib/storage';

export const SW_URL = '/approve-sw.js';
export const SW_SCOPE = '/approve';

export async function registerServiceWorker(): Promise<ServiceWorkerRegistration | null> {
  // The worker is generated by the production build only.
  if (!import.meta.env.PROD || typeof navigator === 'undefined' || !('serviceWorker' in navigator)) return null;
  try {
    return await navigator.serviceWorker.register(SW_URL, { scope: SW_SCOPE });
  } catch (err) {
    console.warn('Service worker registration failed; offline shell and push are unavailable.', err);
    return null;
  }
}

export function postToServiceWorker(message: Record<string, unknown>): void {
  if (typeof navigator !== 'undefined' && 'serviceWorker' in navigator) {
    navigator.serviceWorker.controller?.postMessage(message);
  }
}

/** VAPID public keys are URL-safe base64; PushManager.subscribe wants raw bytes. */
export function urlBase64ToUint8Array(base64: string): Uint8Array {
  const padding = '='.repeat((4 - (base64.length % 4)) % 4);
  const normalized = (base64 + padding).replace(/-/g, '+').replace(/_/g, '/');
  const raw = atob(normalized);
  const out = new Uint8Array(raw.length);
  for (let i = 0; i < raw.length; i++) out[i] = raw.charCodeAt(i);
  return out;
}

export type PushState = 'subscribed' | 'unavailable' | 'error';

/**
 * Best-effort: stop push for this device before signing out, so a shared phone does not keep
 * receiving another person's approval alerts. Must run while the session token is still valid.
 */
export async function disablePushSubscription(api: ApiClient, registration: ServiceWorkerRegistration | null): Promise<void> {
  if (!registration || !('pushManager' in registration)) return;
  try {
    const subscription = await registration.pushManager.getSubscription();
    if (!subscription) return;
    await api.pushUnsubscribe(subscription.endpoint).catch(() => undefined);
    await subscription.unsubscribe();
  } catch (err) {
    console.warn('Web Push unsubscribe failed', err);
  }
}

/**
 * Subscribes to Web Push when the server publishes a VAPID key (GET /api/push/vapid);
 * otherwise live SSE + page notifications are used. Requires notification permission.
 */
export async function ensurePushSubscription(api: ApiClient, registration: ServiceWorkerRegistration | null): Promise<PushState> {
  if (!registration || !('PushManager' in window) || Notification.permission !== 'granted') return 'unavailable';
  try {
    const key = await api.vapidKey();
    if (!key) return 'unavailable';
    let subscription = await registration.pushManager.getSubscription();
    if (!subscription) {
      subscription = await registration.pushManager.subscribe({
        userVisibleOnly: true,
        applicationServerKey: urlBase64ToUint8Array(key) as BufferSource,
      });
    }
    await api.pushSubscribe(subscription.toJSON());
    return 'subscribed';
  } catch (err) {
    console.warn('Web Push subscription failed', err);
    return 'error';
  }
}

interface BeforeInstallPromptEvent extends Event {
  prompt(): Promise<void>;
  userChoice: Promise<{ outcome: 'accepted' | 'dismissed' }>;
}

const INSTALL_DISMISSED_KEY = 'mirsad.installDismissed';

export function isStandalone(): boolean {
  if (typeof window === 'undefined') return false;
  const nav = navigator as Navigator & { standalone?: boolean };
  return (typeof window.matchMedia === 'function' && window.matchMedia('(display-mode: standalone)').matches) || nav.standalone === true;
}

export function isIos(): boolean {
  if (typeof navigator === 'undefined') return false;
  return /iphone|ipad|ipod/i.test(navigator.userAgent) || (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1);
}

/** Captures `beforeinstallprompt` (Chromium/Android); iOS gets manual instructions instead. */
export function useInstallPrompt() {
  const [deferred, setDeferred] = useState<BeforeInstallPromptEvent | null>(null);
  const [dismissed, setDismissed] = useState(() => localStore.getItem(INSTALL_DISMISSED_KEY) === '1');
  const [installed, setInstalled] = useState(isStandalone);

  useEffect(() => {
    const onPrompt = (e: Event) => {
      e.preventDefault();
      setDeferred(e as BeforeInstallPromptEvent);
    };
    const onInstalled = () => setInstalled(true);
    window.addEventListener('beforeinstallprompt', onPrompt);
    window.addEventListener('appinstalled', onInstalled);
    return () => {
      window.removeEventListener('beforeinstallprompt', onPrompt);
      window.removeEventListener('appinstalled', onInstalled);
    };
  }, []);

  const install = useCallback(async () => {
    if (!deferred) return;
    await deferred.prompt();
    const choice = await deferred.userChoice.catch(() => ({ outcome: 'dismissed' as const }));
    if (choice.outcome === 'accepted') setInstalled(true);
    setDeferred(null);
  }, [deferred]);

  const dismiss = useCallback(() => {
    localStore.setItem(INSTALL_DISMISSED_KEY, '1');
    setDismissed(true);
  }, []);

  const mode: 'prompt' | 'ios' | null = installed || dismissed ? null : deferred ? 'prompt' : isIos() ? 'ios' : null;
  return { mode, install, dismiss };
}

export type ApproverRoute = { view: 'pending' } | { view: 'history' } | { view: 'detail'; id: string };

/**
 * '#/a/<id>' (detail; '#/approvals/<id>' is accepted too, it is the link the server puts in
 * Web Push payloads), '#/history', anything else is the pending list.
 */
export function parseApproverRoute(path: string): ApproverRoute {
  const m = /^\/(?:a|approvals)\/([^/?#]+)\/?$/.exec(path);
  if (m) {
    try {
      return { view: 'detail', id: decodeURIComponent(m[1]) };
    } catch {
      return { view: 'pending' };
    }
  }
  return path === '/history' ? { view: 'history' } : { view: 'pending' };
}

/** Tiny hash router over `location.hash` (see parseApproverRoute for the paths). */
export function useHashRoute(): [string, (path: string) => void] {
  const read = () => (typeof window === 'undefined' ? '/' : window.location.hash.replace(/^#/, '') || '/');
  const [path, setPath] = useState(read);
  useEffect(() => {
    const onChange = () => setPath(read());
    window.addEventListener('hashchange', onChange);
    return () => window.removeEventListener('hashchange', onChange);
  }, []);
  const navigate = useCallback((next: string) => {
    if (read() !== next) window.location.hash = next;
  }, []);
  return [path, navigate];
}
